const client = await pool.connect();
try {
  await client.query('BEGIN');
  await client.query(
    'SELECT id FROM orders WHERE id = $1 FOR UPDATE', [id]); // root lock
  await applyCluster(client, id);   // members need no own locks
  await client.query('COMMIT');
} catch (e) {
  await client.query('ROLLBACK');
  throw e;
} finally {
  client.release();
}
